from pathlib import Path
root=Path(__file__).resolve().parent
base='''*{box-sizing:border-box}html,body{margin:0;width:1440px;height:900px}body{font-family:Arial,Helvetica,sans-serif;font-size:18px;line-height:1.25;font-variant-numeric:tabular-nums}h1,h2,h3,p,figure{margin:0}h1,h2,h3{font-weight:400}img{display:block;width:100%;height:100%;object-fit:cover;image-rendering:auto}small,.small{font-size:16px}strong{font-weight:700}.score{font-weight:900;letter-spacing:-.085em;line-height:.8}.score span{font-size:32px;font-weight:400;letter-spacing:-1px}.play{display:inline-block;width:0;height:0;border-left:11px solid currentColor;border-top:7px solid transparent;border-bottom:7px solid transparent;margin-right:8px}.sample{font-size:16px}.photo{position:relative}.label{position:absolute;padding:9px 12px;background:#000;color:#fff;font-size:18px}.failure h3{font-size:20px}.failure p{font-size:16px;margin-top:4px}'''
def write(name,css,body):
 (root/name).write_text(f'<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CrashLab — {name[10]}</title><style>{base}\n{css}</style></head><body>{body}</body></html>\n')
def img(name,alt,extra=''):
 return f'<img src="real-frames/{name}.png" alt="{alt}" {extra}>'
cases=[('task0-2','Wrong object','Plate moved 4 cm','Variation bot'),('task1-2','Wrong object','Extra bowl added','AI tester'),('task2-3','Collision','Clutter added','Human'),('task0-3','Dropped object','Dim light','Variation bot'),('task3-1','Timed out','Bowl moved back','Human'),('task3-2','Collision','Tall obstacle','AI tester')]
def failures():
 return ''.join(f'<article class="failure {"active" if i==0 else ""}"><div class="thumb">{img(f[0],"Simulator frame for sample "+f[1].lower()+" case")}</div><h3>{f[1]}</h3><p>{f[2]}</p><p>{f[3]}</p><p class="watch">{"Opened replay" if i==0 else "▷ Watch replay"}</p></article>' for i,f in enumerate(cases))
css='''body{background:#ffcf00;color:#000}main{display:grid;grid-template-columns:420px 1020px;height:900px}.verdict{padding:32px;display:flex;flex-direction:column}.brand{font-size:24px}.verdict h1{font-size:42px;margin-top:28px;letter-spacing:-1.5px}.task{font-size:23px;margin-top:10px;max-width:310px}.score{font-size:260px;margin:30px 0 20px -12px}.verdict h2{font-size:48px;line-height:1;letter-spacing:-2px}.stat{margin-top:20px;font-size:20px}.contract{margin-top:auto;border-top:4px solid #000;padding-top:18px}.contract h3{font-size:32px;margin-bottom:8px}.sample{margin-top:24px}.evidence{display:grid;grid-template-rows:566px 334px;background:#000;color:#fff}.hero{position:relative;min-height:0;height:566px}.hero img{position:absolute;inset:0;object-position:50% 76%}.hero:after{content:"";position:absolute;left:12%;top:58%;width:24%;height:16%;border:5px solid #ffcf00;pointer-events:none}.hero .label{top:24px;left:24px;z-index:2}.failure-title{position:absolute;z-index:2;bottom:30px;left:26px;background:#ffcf00;color:#000;padding:12px 18px;font-size:64px;line-height:1;letter-spacing:-3px}.time{position:absolute;bottom:32px;right:24px;background:#000;padding:10px 12px;font-size:20px}.library{padding:20px 24px}.library-head{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:16px}.library-head h2{font-size:24px}.failures{display:grid;grid-template-columns:repeat(6,1fr);gap:12px}.thumb{height:80px;margin-bottom:10px}.thumb img{object-position:30% 65%}.failure h3{font-size:18px}.failure p{line-height:1.3}.watch{margin-top:10px!important;color:#ffcf00}.active .thumb{outline:3px solid #ffcf00;outline-offset:-3px}.trace{display:flex;justify-content:space-between;margin-top:12px;border-top:1px solid #777;padding-top:12px;font-size:16px}'''
body=f'''<main><aside class="verdict"><p class="brand">CrashLab</p><h1>SmolVLA</h1><p class="task">Put the bowl on the plate.</p><div class="score">71<span>/100</span></div><h2>Test failed.</h2><p class="stat">213 / 300 scenes passed.<br>This fix fails the test.</p><section class="contract"><h3>5,000 USDC</h3><p>Held in contract.<br>90 / 100 required for payout.</p></section><p class="sample">Sample data</p></aside><section class="evidence"><figure class="hero">{img('task0-2','Robot gripper lifting the plate; the bowl remains on the table')}<figcaption class="label">Opened replay / Wrong object</figcaption><div class="failure-title">It lifted the plate.</div><span class="time">2.84 / 8.00 s</span></figure><section class="library"><div class="library-head"><h2>Six ways it breaks.</h2><span class="small">87 failed scenes / 6 cases</span></div><div class="failures">{failures()}</div><div class="trace"><span>0.00 s Reach</span><span>1.20 s Grip plate</span><span style="color:#ffcf00">2.84 s Wrong object lifted</span></div></section></section></main>'''
write('direction-a.html',css,body)
css='''body{background:#fff;color:#000}main{height:900px;display:grid;grid-template-rows:190px 350px 72px 218px 70px}.headline{display:grid;grid-template-columns:1fr 340px 300px;gap:24px;padding:24px 32px;align-items:center}.headline h1{font-size:68px;letter-spacing:-3px;line-height:.95}.headline .score{font-size:176px}.identity h2{font-size:32px;margin:12px 0 8px}.identity p{font-size:18px}.film{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-template-rows:350px;height:350px;min-height:0;gap:4px;background:#000}.film figure{position:relative;min-width:0;min-height:0;height:350px}.film img{position:absolute;inset:0;width:100%;height:350px;object-position:50% 75%}.film figcaption{position:absolute;z-index:2;left:18px;top:18px;background:#fff;padding:8px 12px;font-size:20px}.film .impact{outline:8px solid #ff4a18;outline-offset:-8px}.impact figcaption{background:#ff4a18;color:#000}.impact:after{content:"";position:absolute;left:10%;top:65%;width:29%;height:20%;border:5px solid #ff4a18;pointer-events:none}.timeline{background:#ff4a18;display:grid;grid-template-columns:repeat(3,1fr);align-items:center;padding:0 32px;gap:32px}.timeline p{font-size:22px}.timeline span{margin-right:20px;font-size:18px}.library{padding:18px 32px}.library-head{display:flex;justify-content:space-between;margin-bottom:14px;align-items:center}.library-head h2{font-size:24px}.failures{display:grid;grid-template-columns:repeat(6,1fr);gap:20px}.failure{display:grid;grid-template-columns:72px 1fr;column-gap:10px;align-content:start}.thumb{grid-row:1/5;height:112px}.thumb img{object-position:22% 65%}.failure h3{font-size:18px;line-height:1.15}.failure p{font-size:16px;line-height:1.25}.watch{margin-top:8px!important;text-decoration:underline;text-underline-offset:3px}.active .thumb{border-bottom:6px solid #ff4a18}.footer{background:#000;color:#fff;padding:0 32px;display:flex;align-items:center;justify-content:space-between}.footer p{font-size:20px}.footer .small{font-size:16px}'''
body=f'''<main><section class="headline"><h1>Bowl requested.<br>Plate lifted.</h1><div class="identity"><p>CrashLab / Crash test report</p><h2>SmolVLA</h2><p>Put the bowl on the plate.</p></div><div class="score">71<span>/100</span></div></section><section class="film" aria-label="Opened replay, wrong object: three sequential frames"><figure>{img('task0-0','Gripper approaches the bowl and plate')}<figcaption>0.00 s / Approach</figcaption></figure><figure>{img('task0-1','Gripper closes above the plate')}<figcaption>1.20 s / Wrong target</figcaption></figure><figure class="impact">{img('task0-2','Plate tilted and lifted by the gripper')}<figcaption>2.84 s / Plate lifted</figcaption></figure></section><section class="timeline" aria-label="Replay timeline"><p><span>0.00 s</span>Reach</p><p><span>1.20 s</span>Grip the plate</p><p><span class="play"></span>Plate lifted. Test failed.</p></section><section class="library"><div class="library-head"><h2>The failure library</h2><p class="small">213 / 300 scenes passed. 87 failed scenes, 6 cases.</p></div><div class="failures">{failures()}</div></section><footer class="footer"><p>This fix fails. <span style="color:#ff845e">5,000 USDC stays locked.</span></p><span class="small">Pass threshold: 90 / 100</span><span class="small">Scene: bowl-placement / Seed 1842</span><span class="small">Sample data</span></footer></main>'''
write('direction-b.html',css,body)
css='''body{background:#243dff;color:#fff}main{padding:28px 32px;height:900px;display:grid;grid-template-rows:172px 606px 66px}.hero{display:grid;grid-template-columns:1fr 364px;align-items:start;gap:32px}.hero h1{font-size:98px;line-height:.95;letter-spacing:-5px;margin-top:15px}.hero p{font-size:24px;line-height:1.2;margin-top:36px}.brand{font-size:20px}.tests{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.test{border-top:4px solid #fff;display:grid;grid-template-rows:66px 280px 48px 180px 28px}.test h2{font-size:30px;line-height:1.1;align-self:center;letter-spacing:-.7px}.photo{height:280px;min-height:0}.photo img{position:absolute;inset:0;height:232px;object-position:40% 75%}.photo .label{bottom:0;left:0;width:100%;height:48px;padding:8px 14px;background:#ffe500;color:#000;font-size:26px;line-height:32px;z-index:2}.photo:after{content:"";position:absolute;left:10%;top:132px;width:32%;height:72px;border:4px solid #ffe500;pointer-events:none}.test:nth-child(2) .photo img{object-position:40% 15%}.test:nth-child(2) .photo:after{left:0;top:106px;width:23%;height:102px}.test:nth-child(3) .photo:after{left:9%;top:139px;width:30%;height:82px}.columns{display:grid;grid-template-columns:60px 1fr 130px;align-items:center;font-size:16px;border-bottom:1px solid #fff}.columns span:last-child{text-align:right}.rank{display:grid;grid-template-columns:60px 1fr 130px;align-items:center;height:60px;border-bottom:1px solid #7e8eff;font-size:24px}.rank .value{text-align:right;white-space:nowrap}.rank .value span{font-size:20px}.rank.winner{background:#fff;color:#243dff}.rank .number,.columns span:first-child{padding-left:10px}.rank .number{font-size:18px}.detail{font-size:16px;padding-top:9px}.footer{display:flex;justify-content:space-between;align-items:end;padding-bottom:1px;border-top:2px solid #fff;margin-top:20px;font-size:16px}.footer p:first-child{font-size:20px}'''
tests=[('Bowl on plate','task0-2','Wrong object',[('Model A','86','3'),('SmolVLA','71','4'),('Model B','64','5')],'Placement / 300 scenes'),('Find the right bowl','task1-2','Wrong bowl',[('SmolVLA','82','3'),('Model B','77','4'),('Model A','69','5')],'Object choice / 300 scenes'),('Reach through clutter','task2-3','Plate contact',[('Model B','79','4'),('Model A','73','3'),('SmolVLA','58','6')],'Collision avoidance / 300 scenes')]
cards=''
for title,photo,label,ranking,detail in tests:
 rows=''.join(f'<div class="rank {"winner" if i==0 else ""}"><span class="number">{i+1}</span><span>{name}</span><span class="value">{score} <span>± {spread}</span></span></div>' for i,(name,score,spread) in enumerate(ranking))
 cards+=f'<article class="test"><h2>{title}</h2><figure class="photo">{img(photo,"Simulator example: "+label.lower())}<figcaption class="label">{label}</figcaption></figure><div class="columns"><span>Rank</span><span>Model</span><span>Score / 100</span></div><div>{rows}</div><p class="detail">{detail}</p></article>'
body=f'''<main><section class="hero"><div><div class="brand">CrashLab / Robot AI leaderboard</div><h1>Tested to failure.</h1></div><p>People find the edge cases.<br>AI runs them at scale.<br>Every score has evidence.</p></section><section class="tests">{cards}</section><footer class="footer"><p>Three tests. No hiding the misses.</p><span>± shows an illustrative range.</span><span>Sample data</span></footer></main>'''
write('direction-c.html',css,body)
